fn e(x:impl std::fmt::Display)->Error{Error::new(x.to_string())}
pub fn oid(s:&str)->Result<()>{if !matches!(s.len(),40|64)||!s.bytes().all(|b|b.is_ascii_hexdigit()&&!b.is_ascii_uppercase()){return Err(e("invalid full Git object id"))}Ok(())}
