fn s(b:Vec<u8>)->Result<String>{String::from_utf8(b).map_err(e)}
fn d<R:Read>(mut r:R,q:Arc<AtomicBool>)->std::io::Result<Vec<u8>>{let mut b=Vec::new();r.by_ref().take((util::MAX_BYTES+1) as u64).read_to_end(&mut b)?;if b.len()>util::MAX_BYTES{q.store(true,Ordering::Relaxed);let mut q=[0u8;8192];while r.read(&mut q)?!=0{};return Err(std::io::Error::other("Git output exceeds limit"))}Ok(b)}
