 pub fn try_run(&self,a:&[&str],b:Option<&[u8]>)->Result<(i32,Vec<u8>,Vec<u8>)>{let r=self.x(a,b)?;Ok((r.status.code().unwrap_or(128),r.stdout,r.stderr))}
 pub fn run(&self,a:&[&str],b:Option<&[u8]>)->Result<Vec<u8>>{let r=self.x(a,b)?;if !r.status.success(){return Err(e(format!("git {} failed ({})",a.first().unwrap_or(&""),r.status)))}Ok(r.stdout)}
 fn id(&self,b:Vec<u8>)->Result<String>{let z=s(b)?.trim().to_owned();oid(&z)?;if z.len()!=self.n{return Err(e("Git returned mismatched hash format"))}Ok(z)}
 fn infos(&self,ids:&[&str])->Result<Vec<(String,u64)>>{if ids.len()>util::MAX_EVENTS{return Err(e("too many Git metadata requests"))}for id in ids{oid(id)?;if id.len()!=self.n{return Err(e("object hash format mismatch"))}}let mut got=BTreeMap::new();{let c=self.c.lock().map_err(|_|e("Git metadata cache poisoned"))?;for id in ids{if let Some(v)=c.get(*id){got.insert((*id).to_owned(),v.clone());}}}let missing=ids.iter().filter(|x|!got.contains_key(**x)).copied().collect::<BTreeSet<_>>();if !missing.is_empty(){let n=missing.len().checked_mul(self.n+1).filter(|n|*n<=util::MAX_BYTES).ok_or_else(||e("Git metadata request exceeds byte limit"))?;let mut b=Vec::with_capacity(n);for id in &missing{b.extend_from_slice(id.as_bytes());b.push(b'\n');}if b.len()>util::MAX_BYTES{return Err(e("Git metadata request exceeds byte limit"))}let z=s(self.run(&["cat-file","--batch-check"],Some(&b))?)?;let rows=z.strip_suffix('\n').ok_or_else(||e("incomplete Git metadata response"))?.split('\n').collect::<Vec<_>>();if rows.len()!=missing.len(){return Err(e("Git metadata response count mismatch"))}for(id,row)in missing.into_iter().zip(rows){let h=row.split(' ').collect::<Vec<_>>();if h.len()!=3||h[0]!=id||!matches!(h[1],"blob"|"tree"|"commit"|"tag")||h[2].is_empty()||!h[2].bytes().all(|x|x.is_ascii_digit()){return Err(e(format!("missing or malformed Git metadata: {id}")))}let n=h[2].parse::<u64>().map_err(e)?;if n>9007199254740991{return Err(e("Git object size exceeds safe integer range"))}got.insert(id.to_owned(),(h[1].into(),n));}let mut c=self.c.lock().map_err(|_|e("Git metadata cache poisoned"))?;if c.len().saturating_add(got.len())>8192{c.clear()}if got.len()<=8192{c.extend(got.iter().map(|(k,v)|(k.clone(),v.clone())));}}ids.iter().map(|id|got.get(*id).cloned().ok_or_else(||e("Git metadata response missing object"))).collect()}
