 pub fn put_tree(&self,m:&BTreeMap<String,Entry>)->Result<String>{#[derive(Default)]struct N{f:BTreeMap<String,Entry>,d:BTreeMap<String,N>}fn add(n:&mut N,p:&[&str],v:&Entry)->Result<()>{if p.len()==1{if n.d.contains_key(p[0])||n.f.insert(p[0].into(),v.clone()).is_some(){return Err(e("file/directory or duplicate tree path conflict"))}return Ok(())}if n.f.contains_key(p[0]){return Err(e("file/directory tree path conflict"))}add(n.d.entry(p[0].into()).or_default(),&p[1..],v)}fn emit(g:&Git,n:&N)->Result<String>{let mut b=Vec::new();for(k,v)in &n.d{let id=emit(g,v)?;b.extend_from_slice(format!("040000 tree {id}\t{k}").as_bytes());b.push(0)}for(k,v)in &n.f{let t=if v.kind=="gitlink"{"commit"}else{"blob"};b.extend_from_slice(format!("{:06o} {t} {}\t{k}",v.mode,v.id).as_bytes());b.push(0)}g.id(g.run(&["mktree","-z"],Some(&b))?)}if m.len()>util::MAX_EVENTS{return Err(e("too many tree entries"))}let mut n=N::default();for(p,v)in m{util::rel(p)?;oid(&v.id)?;if v.id.len()!=self.n||kind(v.mode)?!=v.kind||v.kind=="dir"{return Err(e("invalid tree entry"))}add(&mut n,&p.split('/').collect::<Vec<_>>(),v)?}emit(self,&n)}
